package com.coffeeshop.model;import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.List;public final class PurchasingModels{private PurchasingModels(){}public record Supplier(long id,String code,String name,String contact,String phone,String email,String address,String notes,boolean active,byte[]version){public Supplier{version=version.clone();}@Override public byte[]version(){return version.clone();}@Override public String toString(){return name+(active?"":" (inactive)");}}public record Item(long id,String code,String name,String unit,boolean active){@Override public String toString(){return name+" · "+unit;}}public record PurchaseItem(long id,long itemId,String itemName,String unit,BigDecimal quantity,BigDecimal unitCost,BigDecimal total,byte[]version){}public record Purchase(long id,String number,long supplierId,String supplierName,LocalDateTime purchasedAt,String status,BigDecimal subtotal,BigDecimal discount,BigDecimal tax,BigDecimal total,String invoice,String notes,byte[]version,List<PurchaseItem>items){public Purchase{version=version.clone();items=List.copyOf(items);}@Override public byte[]version(){return version.clone();}}public record Catalog(List<Supplier>suppliers,List<Item>items,List<Purchase>purchases){public Catalog{suppliers=List.copyOf(suppliers);items=List.copyOf(items);purchases=List.copyOf(purchases);}}}
